    for item in os.listdir(path):
        item_path = os.path.join(path, item)
        if os.path.isdir(item_path):
            if max_depth > 0:
                sub = find_all_json(item_path, max_depth - 1)
                results.extend([item_path, *(s for s in sub if '__路径__' not in str(s))])  # filter out bad paths
        else:
            if item.endswith('.json'):
                results.append(item_path)
    return results

